<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/geop_v8.php';
require_login();check_csrf();geop_v8_boot($pdo);
if (!geop_v8_feature_ready($pdo)) {
    if ((current_user()['perfil'] ?? '') === 'TI') redirect('atualizar_geop_v8');
    http_response_code(503); die('O módulo GEOP V8 aguarda a atualização do banco pelo TI.');
}$user=current_user();$uid=(int)$user['id'];$perfil=strtoupper((string)$user['perfil']);$isTi=$perfil==='TI';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $action=$_POST['action']??'';
  if($action==='gerar_2fa'){
    if(!extension_loaded('openssl'))throw new RuntimeException('OpenSSL não está disponível no servidor.');
    $secret=geop_v8_totp_generate_secret();$_SESSION['totp_setup_secret']=$secret;$msg='Segredo 2FA gerado. Cadastre no autenticador e confirme o código.';
  }elseif($action==='confirmar_2fa'){
    $secret=(string)($_SESSION['totp_setup_secret']??'');$code=(string)($_POST['codigo']??'');if($secret===''||!geop_v8_totp_verify($secret,$code))throw new RuntimeException('Código inválido. Confira o horário do celular e tente novamente.');
    $pdo->prepare("UPDATE usuarios SET totp_secret_enc=?,totp_enabled=1,totp_confirmed_em=NOW() WHERE id=?")->execute([geop_v8_encrypt($secret),$uid]);unset($_SESSION['totp_setup_secret']);geop_v8_security_event($pdo,$uid,'2FA_ATIVADO');$msg='2FA ativado com sucesso.';
  }elseif($action==='desativar_2fa'){
    $senha=(string)($_POST['senha']??'');$st=$pdo->prepare('SELECT senha_hash FROM usuarios WHERE id=?');$st->execute([$uid]);if(!password_verify($senha,(string)$st->fetchColumn()))throw new RuntimeException('Senha atual incorreta.');$pdo->prepare("UPDATE usuarios SET totp_secret_enc=NULL,totp_enabled=0,totp_confirmed_em=NULL WHERE id=?")->execute([$uid]);geop_v8_security_event($pdo,$uid,'2FA_DESATIVADO');$msg='2FA desativado.';
  }elseif($action==='config' && $isTi){
    foreach(['session_idle_minutes','max_login_attempts','login_lock_minutes','os_stale_hours','quality_warning_threshold','upload_max_mb'] as $key) if(isset($_POST[$key])) geop_v8_config_set($pdo,$key,(string)max(1,(int)$_POST[$key]),$uid);
    geop_v8_config_set($pdo,'2fa_ti_required',!empty($_POST['2fa_ti_required'])?'1':'0',$uid);$msg='Políticas de segurança atualizadas.';
  }
 }catch(Throwable $e){$err=$e->getMessage();}
}
$st=$pdo->prepare('SELECT totp_enabled,totp_confirmed_em FROM usuarios WHERE id=?');$st->execute([$uid]);$sec=$st->fetch(PDO::FETCH_ASSOC)?:[];$setup=(string)($_SESSION['totp_setup_secret']??'');
$events=[];if($isTi){$events=$pdo->query("SELECT s.*,u.nome usuario_nome FROM seguranca_eventos s LEFT JOIN usuarios u ON u.id=s.usuario_id ORDER BY s.id DESC LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);}else{$st=$pdo->prepare("SELECT * FROM seguranca_eventos WHERE usuario_id=? ORDER BY id DESC LIMIT 20");$st->execute([$uid]);$events=$st->fetchAll(PDO::FETCH_ASSOC);}render_header('Segurança');
?>
<h1 class="h3 mb-1">Segurança da conta e do GEOP</h1><p class="text-muted mb-3">2FA, sessão, tentativas de login e eventos sensíveis.</p><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif?>
<div class="row g-3"><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Autenticação em dois fatores</h2><?php if(!empty($sec['totp_enabled'])):?><div class="alert alert-success">2FA ativo desde <?=e($sec['totp_confirmed_em']??'')?>.</div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="desativar_2fa"><label class="form-label">Senha atual para desativar</label><input class="form-control mb-2" type="password" name="senha" required><button class="btn btn-outline-danger">Desativar 2FA</button></form><?php elseif($setup):?><p>Cadastre manualmente este segredo em Microsoft Authenticator, Google Authenticator, 1Password ou app TOTP compatível:</p><div class="alert alert-warning"><code class="fs-5 user-select-all"><?=e($setup)?></code><div class="small mt-2">URI TOTP: <span class="text-break"><?=e(geop_v8_totp_uri((string)$user['email'],$setup))?></span></div></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="confirmar_2fa"><label class="form-label">Código de 6 dígitos</label><input class="form-control mb-2" name="codigo" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required><button class="btn btn-primary">Confirmar e ativar</button></form><?php else:?><p class="text-muted">O 2FA é opcional por usuário. Para TI é recomendado ativá-lo antes de tornar a política obrigatória.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="gerar_2fa"><button class="btn btn-primary">Configurar 2FA</button></form><?php endif?></div></div></div>
<?php if($isTi):?><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Políticas</h2><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="config"><?php foreach(['session_idle_minutes'=>'Sessão inativa (min)','max_login_attempts'=>'Tentativas de login','login_lock_minutes'=>'Bloqueio (min)','os_stale_hours'=>'OS parada (h)','quality_warning_threshold'=>'Alerta qualidade (%)','upload_max_mb'=>'Upload recomendado (MB)'] as $key=>$label):?><div class="col-md-6"><label class="form-label"><?=e($label)?></label><input class="form-control" type="number" min="1" name="<?=e($key)?>" value="<?=e((string)geop_v8_config($pdo,$key,1))?>"></div><?php endforeach?><div class="col-12"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="2fa_ti_required" id="req2fa" value="1" <?=geop_v8_config($pdo,'2fa_ti_required',false)?'checked':''?>><label class="form-check-label" for="req2fa">Exigir 2FA para usuários TI</label></div><div class="form-text">Ative somente depois que os usuários TI cadastrarem o 2FA.</div></div><div class="col-12"><button class="btn btn-primary">Salvar políticas</button></div></form></div></div></div><?php endif?></div>
<div class="card mt-3"><div class="card-body"><h2 class="h5">Eventos recentes</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Data</th><th>Usuário</th><th>Tipo</th><th>IP</th><th>Detalhe</th></tr></thead><tbody><?php foreach($events as $ev):?><tr><td><?=e($ev['criado_em'])?></td><td><?=e($ev['usuario_nome']??($user['nome']??'-'))?></td><td><?=e($ev['tipo'])?></td><td><?=e($ev['ip']??'-')?></td><td><?=e($ev['detalhe']??'')?></td></tr><?php endforeach?><?php if(!$events):?><tr><td colspan="5" class="text-muted">Nenhum evento V8 registrado.</td></tr><?php endif?></tbody></table></div></div></div>
<?php render_footer(); ?>
